112	/**
113	 * Discovers and loads all skills in the provided directory.
114	 */
115	export async function loadSkillsFromDir(
116	  dir: string,
117	): Promise<SkillDefinition[]> {
118	  const discoveredSkills: SkillDefinition[] = [];
119	
120	  try {
121	    const absoluteSearchPath = path.resolve(dir);
122	    const stats = await fs.stat(absoluteSearchPath).catch(() => null);
123	    if (!stats || !stats.isDirectory()) {
124	      return [];
125	    }
126	
127	    const pattern = ['SKILL.md', '*/SKILL.md'];
128	    const skillFiles = await glob(pattern, {
129	      cwd: absoluteSearchPath,
130	      absolute: true,
131	      nodir: true,
132	      ignore: ['**/node_modules/**', '**/.git/**'],
133	    });
134	
135	    for (const skillFile of skillFiles) {
136	      const metadata = await loadSkillFromFile(skillFile);
137	      if (metadata) {
138	        discoveredSkills.push(metadata);
139	      }
140	    }
141	
142	    if (discoveredSkills.length === 0) {
143	      const files = await fs.readdir(absoluteSearchPath);
144	      if (files.length > 0) {
145	        debugLogger.debug(
146	          `Failed to load skills from ${absoluteSearchPath}. The directory is not empty but no valid skills were discovered. Please ensure SKILL.md files are present in subdirectories and have valid frontmatter.`,
147	        );
148	      }
149	    }
150	  } catch (error) {
151	    coreEvents.emitFeedback(
152	      'warning',
153	      `Error discovering skills in ${dir}:`,
154	      error,
155	    );
156	  }
157	
158	  return discoveredSkills;
159	}
