/**
 * Platform-specific installation information for the Antigravity companion CLI.
 */
export interface AntigravityInstallInfo {
  /** The human-readable name of the detected platform. */
  platformName: string;
  /** The command the user should run to install the Antigravity CLI. */
  installCmd: string;
}

/**
 * Returns platform-specific installation information for the Antigravity CLI
 * based on the current operating system.
 *
 * @returns The install info for the current platform, or `null` if the platform
 *   is not supported.
 */
export function getAntigravityInstallInfo(): AntigravityInstallInfo | null {
  switch (process.platform) {
    case 'darwin':
      return {
        platformName: 'macOS',
        installCmd:
          'curl -fsSL https://antigravity.google/cli/install.sh | bash',
      };
    case 'linux':
      return {
        platformName: 'Linux',
        installCmd:
          'curl -fsSL https://antigravity.google/cli/install.sh | bash',
      };
    case 'win32':
      // PowerShell exposes the PSModulePath environment variable, which lets us
      // distinguish PowerShell sessions from the classic Command Prompt.
      if (process.env['PSModulePath']) {
        return {
          platformName: 'Windows (PowerShell)',
          installCmd: 'irm https://antigravity.google/cli/install.ps1 | iex',
        };
      }
      return {
        platformName: 'Windows (Command Prompt)',
        installCmd:
          'curl -fsSL https://antigravity.google/cli/install.cmd -o install.cmd && install.cmd && del install.cmd',
      };
    default:
      return null;
  }
}
