              `For more information, see ${ANTIGRAVITY_DOCS_URL}`,
          },
          Date.now(),
        );
      } else {
        context.ui.addItem(
          {
            type: MessageType.INFO,
            text:
              `The Antigravity CLI is not available for your platform.\n` +
              `For more information, see ${ANTIGRAVITY_DOCS_URL}`,
          },
          Date.now(),
        );
      }
      return;
    }

    const helpItem: Omit<HistoryItemHelp, 'id'> = {
      type: MessageType.HELP,
      timestamp: new Date(),
    };

    context.ui.addItem(helpItem);
  },
};
